/**
 * Rendering helpers that reproduce CPython's `print()` / `repr()` output.
 *
 * Only the value kinds this program can emit are covered: booleans, integers
 * (arbitrary precision, hence BigInt), floats, lists and tuples.
 */

/** `True` / `False`, not `true` / `false`. */
export function reprBool(value) {
  return value ? 'True' : 'False';
}

/** Python ints are unbounded, so they travel through the program as BigInt. */
export function reprInt(value) {
  return value.toString();
}

/**
 * repr() of a float: the shortest decimal string that round-trips, always
 * carrying a fractional part or an exponent so it cannot be read back as int.
 */
export function reprFloat(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const sign = value < 0 || Object.is(value, -0) ? '-' : '';
  const x = Math.abs(value);

  if (x === 0) return `${sign}0.0`;

  // CPython switches to exponential notation outside [1e-4, 1e16).
  if (x >= 1e16 || x < 1e-4) return sign + exponential(x);

  let text = shortestFixed(x);
  if (!text.includes('.')) text += '.0';
  return sign + text;
}

/** Shortest round-tripping positional notation for a magnitude in range. */
function shortestFixed(x) {
  const plain = String(x);
  if (!plain.includes('e')) return plain;
  // JS only reaches here for magnitudes it prefers to print exponentially;
  // expand them back to positional form the way Python would.
  for (let precision = 1; precision <= 17; precision += 1) {
    const candidate = x.toPrecision(precision);
    if (Number(candidate) === x) return stripZeros(candidate);
  }
  return stripZeros(x.toPrecision(17));
}

/** `1e+16`, `1.5e-07`: mantissa in [1, 10) plus a two-digit signed exponent. */
function exponential(x) {
  let mantissa = null;
  for (let digits = 0; digits <= 16; digits += 1) {
    const candidate = x.toExponential(digits);
    if (Number(candidate) === x) {
      mantissa = candidate;
      break;
    }
  }
  if (mantissa === null) mantissa = x.toExponential(16);

  const [coefficient, rawExponent] = mantissa.split('e');
  const exponentSign = rawExponent.startsWith('-') ? '-' : '+';
  let exponentDigits = rawExponent.replace(/^[+-]/, '');
  if (exponentDigits.length < 2) exponentDigits = `0${exponentDigits}`;
  return `${coefficient}e${exponentSign}${exponentDigits}`;
}

function stripZeros(text) {
  if (!text.includes('.')) return text;
  return text.replace(/0+$/, '').replace(/\.$/, '');
}

/** `[1, 5]` — elements rendered with their own repr. */
export function reprList(items, itemRepr) {
  return `[${items.map(itemRepr).join(', ')}]`;
}

/** `(1, 2)` — the trailing comma of 1-tuples is honoured. */
export function reprTuple(items, itemRepr) {
  const rendered = items.map(itemRepr);
  if (rendered.length === 1) return `(${rendered[0]},)`;
  return `(${rendered.join(', ')})`;
}

/** repr() of a str, as argparse uses in its error messages. */
export function reprStr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of text) {
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += `\\${ch}`;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else out += ch;
  }
  return `${quote}${out}${quote}`;
}

