/**
 * A hand-rolled subset of `argparse.ArgumentParser`: enough to mirror the
 * accept/reject behaviour, message wording and exit codes of the original
 * Python script's parser.
 */

import { pyInt, IntConversionError } from './pyint.mjs';
import { reprStr } from '../format/pyrepr.mjs';

/** argparse's `_negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** `type=int` for add_argument, carrying the name argparse puts in errors. */
export const intType = Object.assign((text) => pyInt(text), { typeName: 'int' });

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, { action = 'store', type = null, required = false, help = null } = {}) {
    const dest = optionStrings[optionStrings.length - 1].replace(/^--?/, '').replace(/-/g, '_');
    const entry = {
      optionStrings,
      dest,
      action,
      type,
      required,
      help,
      metavar: dest.toUpperCase(),
    };
    this.actions.push(entry);
    for (const optionString of optionStrings) this.optionStringActions.set(optionString, entry);
    return entry;
  }

  /**
   * Parse `argv` (the arguments after the script name). Terminates the process
   * with status 2 on any parse error, exactly as argparse does.
   */
  parseArgs(argv) {
    const namespace = Object.create(null);
    const extras = [];
    const supplied = new Set();
    let positionalsOnly = false;

    for (let index = 0; index < argv.length; ) {
      const token = argv[index];

      // Everything after the first `--` is a positional; the separator itself
      // is left in place because no positional argument is defined to eat it.
      if (positionalsOnly) {
        extras.push(token);
        index += 1;
        continue;
      }
      if (token === '--') {
        positionalsOnly = true;
        extras.push(token);
        index += 1;
        continue;
      }

      const optional = this.parseOptional(token);
      if (optional === null || optional.action === null) {
        extras.push(token);
        index += 1;
        continue;
      }

      const { action, optionString } = optional;
      let { explicitArg } = optional;
      index += 1;

      if (action.action === 'help') {
        if (explicitArg !== null) {
          this.error(`argument ${actionName(action)}: ignored explicit argument ${reprStr(explicitArg)}`);
        }
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      if (explicitArg === null) {
        const next = index < argv.length ? argv[index] : null;
        if (next === null || this.parseOptional(next) !== null) {
          this.error(`argument ${actionName(action)}: expected one argument`);
        }
        explicitArg = next;
        index += 1;
      }

      namespace[action.dest] = this.convert(action, explicitArg);
      supplied.add(action);
    }

    const missing = this.actions.filter((action) => action.required && !supplied.has(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.map(actionName).join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  convert(action, text) {
    if (action.type === null) return text;
    try {
      return action.type(text);
    } catch (err) {
      if (err instanceof IntConversionError) {
        const name = action.type.typeName ?? 'value';
        this.error(`argument ${actionName(action)}: invalid ${name} value: ${reprStr(text)}`);
      }
      throw err;
    }
  }

  /**
   * argparse's `_parse_optional`. Returns null when the token is a positional,
   * `{action: null, ...}` for an unknown option, or the matched action.
   */
  parseOptional(token) {
    if (token.length === 0) return null;
    if (token[0] !== '-') return null;

    const exact = this.optionStringActions.get(token);
    if (exact !== undefined) return { action: exact, optionString: token, explicitArg: null };

    if (token.length === 1) return null; // a bare "-" is a positional

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const optionString = token.slice(0, equals);
      const matched = this.optionStringActions.get(optionString);
      if (matched !== undefined) {
        return { action: matched, optionString, explicitArg: token.slice(equals + 1) };
      }
    }

    const candidates = this.optionTuples(token);
    if (candidates.length > 1) {
      const names = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    if (candidates.length === 1) return candidates[0];

    // No option looks like a negative number, so "-3" is a value, not a flag.
    if (NEGATIVE_NUMBER.test(token)) return null;
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitArg: null };
  }

  /** Abbreviated long options, and `-xVALUE` style short options. */
  optionTuples(token) {
    const result = [];
    if (token.startsWith('--')) {
      const equals = token.indexOf('=');
      const prefix = equals === -1 ? token : token.slice(0, equals);
      const explicitArg = equals === -1 ? null : token.slice(equals + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(prefix)) result.push({ action, optionString, explicitArg });
      }
    } else {
      const shortPrefix = token.slice(0, 2);
      const shortExplicitArg = token.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(token)) {
          result.push({ action, optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation = `${action.optionStrings[0]}${action.action === 'help' ? '' : ` ${action.metavar}`}`;
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map(invocationOf);
    const actionMaxLength = Math.max(...invocations.map((text) => text.length + INDENT));
    const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);

    const lines = this.actions.map((action, position) => {
      const invocation = `${' '.repeat(INDENT)}${invocations[position]}`;
      if (action.help === null) return invocation;
      return `${invocation.padEnd(helpPosition)}${action.help}`;
    });

    return `${this.formatUsage()}\noptions:\n${lines.join('\n')}\n`;
  }

  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }
}

/** argparse's `_get_action_name`. */
function actionName(action) {
  return action.optionStrings.join('/');
}

function invocationOf(action) {
  if (action.action === 'help') return action.optionStrings.join(', ');
  return action.optionStrings.map((optionString) => `${optionString} ${action.metavar}`).join(', ');
}

