/**
 * An undirected graph with the storage semantics the reference implementation
 * relies on: nodes and adjacency preserve insertion order, parallel edges
 * collapse onto the existing edge (updating its data), and self-loops are kept
 * and counted twice by `degree`.
 *
 * Node identifiers are BigInt so arbitrarily large integers stay exact.
 */
export class Graph {
  constructor() {
    this.nodeAttributes = new Map(); // node -> attribute object
    this.adjacency = new Map(); // node -> Map(neighbour -> shared edge data)
  }

  addNode(node, attributes = {}) {
    if (this.adjacency.has(node)) {
      Object.assign(this.nodeAttributes.get(node), attributes);
      return;
    }
    this.adjacency.set(node, new Map());
    this.nodeAttributes.set(node, { ...attributes });
  }

  addNodesFrom(nodes) {
    for (const node of nodes) this.addNode(node);
  }

  /** Adding an existing edge merges into (and so overwrites) its data. */
  addEdge(u, v, attributes = {}) {
    this.addNode(u);
    this.addNode(v);
    const existing = this.adjacency.get(u).get(v);
    if (existing !== undefined) {
      Object.assign(existing, attributes);
      return;
    }
    const data = { ...attributes };
    this.adjacency.get(u).set(v, data);
    this.adjacency.get(v).set(u, data); // one shared object, as in the original
  }

  addEdgesFrom(edges) {
    for (const [u, v, attributes] of edges) this.addEdge(u, v, attributes);
  }

  /** `[u, v, weight]` triples, stored under the given attribute name. */
  addWeightedEdgesFrom(edges, weightKey = 'weight') {
    for (const [u, v, weight] of edges) this.addEdge(u, v, { [weightKey]: weight });
  }

  nodes() {
    return [...this.adjacency.keys()];
  }

  hasNode(node) {
    return this.adjacency.has(node);
  }

  /** The neighbour map of `node`, in insertion order. */
  neighbourMap(node) {
    return this.adjacency.get(node);
  }

  neighbours(node) {
    return [...this.adjacency.get(node).keys()];
  }

  hasEdge(u, v) {
    const neighbours = this.adjacency.get(u);
    return neighbours !== undefined && neighbours.has(v);
  }

  getEdgeData(u, v) {
    const neighbours = this.adjacency.get(u);
    return neighbours === undefined ? undefined : neighbours.get(v);
  }

  /** Self-loops contribute 2, matching the reference `degree`. */
  degree(node) {
    const neighbours = this.adjacency.get(node);
    return neighbours.size + (neighbours.has(node) ? 1 : 0);
  }

  /** `[node, degree]` pairs in node insertion order. */
  degrees() {
    return this.nodes().map((node) => [node, this.degree(node)]);
  }

  /** Each edge once, as `[u, v, data]`, in the reference iteration order. */
  edges() {
    const result = [];
    const seen = new Set();
    for (const [node, neighbours] of this.adjacency) {
      for (const [neighbour, data] of neighbours) {
        if (!seen.has(neighbour)) result.push([node, neighbour, data]);
      }
      seen.add(node);
    }
    return result;
  }

  numberOfNodes() {
    return this.adjacency.size;
  }

  /** Half the degree sum: a self-loop counts as one edge. */
  numberOfEdges() {
    let total = 0;
    for (const node of this.adjacency.keys()) total += this.degree(node);
    return total / 2;
  }
}

