/** Disjoint-set forest with union by size and path compression. */
export class UnionFind {
  constructor() {
    this.parent = new Map();
    this.weight = new Map();
  }

  /** The representative of `item`, inserting it on first sight. */
  find(item) {
    if (!this.parent.has(item)) {
      this.parent.set(item, item);
      this.weight.set(item, 1);
      return item;
    }
    let root = item;
    while (this.parent.get(root) !== root) root = this.parent.get(root);
    let cursor = item;
    while (this.parent.get(cursor) !== root) {
      const next = this.parent.get(cursor);
      this.parent.set(cursor, root);
      cursor = next;
    }
    return root;
  }

  union(a, b) {
    const rootA = this.find(a);
    const rootB = this.find(b);
    if (rootA === rootB) return;
    const [big, small] = this.weight.get(rootA) >= this.weight.get(rootB) ? [rootA, rootB] : [rootB, rootA];
    this.weight.set(big, this.weight.get(big) + this.weight.get(small));
    this.parent.set(small, big);
  }
}

