/**
 * Binary min-heap over `[priority, sequence, payload]` entries, ordered by
 * priority and then by insertion sequence. The sequence number makes the order
 * total, so the pop order is fully determined by insertion history — which is
 * what keeps tie-broken shortest paths identical to the reference behaviour.
 */
export class PriorityQueue {
  constructor() {
    this.items = [];
  }

  get size() {
    return this.items.length;
  }

  push(priority, sequence, payload) {
    const items = this.items;
    items.push([priority, sequence, payload]);
    let child = items.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (!precedes(items[child], items[parent])) break;
      [items[child], items[parent]] = [items[parent], items[child]];
      child = parent;
    }
  }

  pop() {
    const items = this.items;
    const top = items[0];
    const last = items.pop();
    if (items.length > 0) {
      items[0] = last;
      let parent = 0;
      for (;;) {
        const left = parent * 2 + 1;
        const right = left + 1;
        let smallest = parent;
        if (left < items.length && precedes(items[left], items[smallest])) smallest = left;
        if (right < items.length && precedes(items[right], items[smallest])) smallest = right;
        if (smallest === parent) break;
        [items[parent], items[smallest]] = [items[smallest], items[parent]];
        parent = smallest;
      }
    }
    return top;
  }
}

function precedes(a, b) {
  if (a[0] !== b[0]) return a[0] < b[0];
  return a[1] < b[1];
}

