/** Breadth-first and depth-first edge traversals. */

/**
 * Edges of a breadth-first search from `source`, in discovery order.
 * Neighbours are visited in adjacency insertion order.
 */
export function bfsEdges(graph, source) {
  const edges = [];
  if (!graph.hasNode(source)) return edges;

  const visited = new Set([source]);
  const queue = [source];
  while (queue.length > 0) {
    const parent = queue.shift();
    for (const child of graph.neighbourMap(parent).keys()) {
      if (visited.has(child)) continue;
      edges.push([parent, child]);
      visited.add(child);
      queue.push(child);
    }
  }
  return edges;
}

/**
 * Edges of a depth-first search from `source`, in pre-order. The explicit
 * stack of neighbour iterators reproduces the reference traversal order.
 */
export function dfsEdges(graph, source) {
  const edges = [];
  if (!graph.hasNode(source)) return edges;

  const visited = new Set([source]);
  const stack = [[source, graph.neighbourMap(source).keys()]];
  while (stack.length > 0) {
    const [parent, children] = stack[stack.length - 1];
    let descended = false;
    for (;;) {
      const step = children.next();
      if (step.done) break;
      const child = step.value;
      if (visited.has(child)) continue;
      edges.push([parent, child]);
      visited.add(child);
      stack.push([child, graph.neighbourMap(child).keys()]);
      descended = true;
      break;
    }
    if (!descended) stack.pop();
  }
  return edges;
}

