/** Dijkstra shortest paths on non-negative weighted graphs. */

import { PriorityQueue } from '../structures/heap.mjs';

export class NoPathError extends Error {}

/**
 * Single-source Dijkstra, stopping early at `target`.
 *
 * Ties are resolved the same way as the reference implementation: a node is
 * only re-pushed when a strictly shorter distance is found, so among equally
 * long routes the first one discovered is the one reported.
 */
export function singleSourceDijkstra(graph, source, target, weightKey = 'weight') {
  const distances = new Map();
  const seen = new Map([[source, 0]]);
  const paths = new Map([[source, [source]]]);
  const fringe = new PriorityQueue();
  let sequence = 0;

  fringe.push(0, sequence++, source);
  while (fringe.size > 0) {
    const [distance, , node] = fringe.pop();
    if (distances.has(node)) continue;
    distances.set(node, distance);
    if (node === target) break;

    for (const [neighbour, data] of graph.neighbourMap(node)) {
      const cost = data[weightKey] ?? 1;
      const candidate = distance + cost;
      if (distances.has(neighbour)) continue;
      if (seen.has(neighbour) && candidate >= seen.get(neighbour)) continue;
      seen.set(neighbour, candidate);
      fringe.push(candidate, sequence++, neighbour);
      paths.set(neighbour, [...paths.get(node), neighbour]);
