/** Minimum spanning tree via Kruskal's algorithm. */

import { Graph } from '../graph/graph.mjs';
import { UnionFind } from '../structures/unionfind.mjs';

/**
 * Edges of a minimum spanning forest, lightest first.
 *
 * The sort is stable over the graph's own edge order, and self-loops fall out
 * naturally because both endpoints already share a subtree.
 */
export function minimumSpanningEdges(graph, weightKey = 'weight') {
  const candidates = graph.edges().map(([u, v, data], position) => ({
    u,
    v,
    data,
    position,
    weight: data[weightKey] ?? 1,
  }));
  candidates.sort((a, b) => (a.weight === b.weight ? a.position - b.position : a.weight - b.weight));

  const subtrees = new UnionFind();
  const chosen = [];
  for (const { u, v, data } of candidates) {
    if (subtrees.find(u) === subtrees.find(v)) continue;
    chosen.push([u, v, data]);
    subtrees.union(u, v);
  }
  return chosen;
}

/** A minimum spanning tree carrying every node of `graph`. */
export function minimumSpanningTree(graph, weightKey = 'weight') {
  const tree = new Graph();
  for (const node of graph.nodes()) tree.addNode(node, graph.nodeAttributes.get(node));
  for (const [u, v, data] of minimumSpanningEdges(graph, weightKey)) tree.addEdge(u, v, { ...data });
  return tree;
}

