/**
 * Maximum flow on a small unit-capacity digraph, by repeated breadth-first
 * augmentation (Edmonds–Karp). The maximum flow *value* is unique, so the
 * choice of augmenting strategy does not affect the result.
 */
export class FlowNetwork {
  constructor(nodeCount) {
    this.adjacency = Array.from({ length: nodeCount }, () => []);
    this.edges = []; // flattened [to, capacity] pairs, each followed by its reverse
  }

  addEdge(from, to, capacity) {
    this.adjacency[from].push(this.edges.length);
    this.edges.push({ to, capacity });
    this.adjacency[to].push(this.edges.length);
    this.edges.push({ to: from, capacity: 0 });
  }

  maxFlowValue(source, sink) {
    if (source === sink) return 0;
    let flow = 0;
    for (;;) {
      const path = this.findAugmentingPath(source, sink);
      if (path === null) return flow;
      let bottleneck = Infinity;
      for (const index of path) bottleneck = Math.min(bottleneck, this.edges[index].capacity);
      for (const index of path) {
        this.edges[index].capacity -= bottleneck;
        this.edges[index ^ 1].capacity += bottleneck;
      }
      flow += bottleneck;
    }
  }

  /** Shortest residual path from source to sink, as a list of edge indices. */
  findAugmentingPath(source, sink) {
    const incoming = new Array(this.adjacency.length).fill(-1);
    const visited = new Array(this.adjacency.length).fill(false);
    visited[source] = true;

    const queue = [source];
    while (queue.length > 0) {
      const node = queue.shift();
      for (const index of this.adjacency[node]) {
        const edge = this.edges[index];
        if (edge.capacity <= 0 || visited[edge.to]) continue;
        visited[edge.to] = true;
        incoming[edge.to] = index;
        if (edge.to === sink) {
          const path = [];
          for (let index2 = incoming[sink]; index2 !== -1; ) {
            path.push(index2);
            const previous = this.edges[index2 ^ 1].to;
            index2 = incoming[previous];
          }
          return path;
        }
        queue.push(edge.to);
      }
    }
    return null;
  }
}

