/** Node connectivity: the fewest nodes whose removal disconnects the graph. */

import { FlowNetwork } from '../structures/flow_network.mjs';

/** Whether every node is reachable from an arbitrary starting node. */
export function isConnected(graph) {
  const nodes = graph.nodes();
  if (nodes.length === 0) throw new Error('Connectivity is undefined for the null graph.');

  const visited = new Set([nodes[0]]);
  const queue = [nodes[0]];
  while (queue.length > 0) {
    const node = queue.shift();
    for (const neighbour of graph.neighbourMap(node).keys()) {
      if (visited.has(neighbour)) continue;
      visited.add(neighbour);
      queue.push(neighbour);
    }
  }
  return visited.size === nodes.length;
}

/**
 * Number of internally node-disjoint paths between two non-adjacent nodes,
 * computed as a maximum flow over the split-node ("node capacity") digraph:
 * every node becomes an in-half and an out-half joined by a unit-capacity arc.
 */
export function localNodeConnectivity(graph, source, target) {
  const nodes = graph.nodes();
  const index = new Map(nodes.map((node, position) => [node, position]));
  const inHalf = (position) => position * 2;
  const outHalf = (position) => position * 2 + 1;

  const network = new FlowNetwork(nodes.length * 2);
  for (let position = 0; position < nodes.length; position += 1) {
    network.addEdge(inHalf(position), outHalf(position), 1);
  }
  const added = new Set();
  for (const [u, v] of graph.edges()) {
    for (const [from, to] of [
      [index.get(u), index.get(v)],
      [index.get(v), index.get(u)],
    ]) {
      const key = `${from},${to}`;
      if (added.has(key)) continue;
      added.add(key);
      network.addEdge(outHalf(from), inHalf(to), 1);
    }
  }
  return network.maxFlowValue(outHalf(index.get(source)), inHalf(index.get(target)));
}

/**
 * Global node connectivity.
 *
 * Anchored at a node `v` of minimum degree (which bounds the answer): the
 * connectivity is the smallest local connectivity between `v` and each of its
 * non-neighbours, and between each non-adjacent pair of its neighbours.
 */
export function nodeConnectivity(graph) {
  if (!isConnected(graph)) return 0;

  let anchor = null;
  let connectivity = Infinity;
  for (const [node, degree] of graph.degrees()) {
    if (degree < connectivity) {
      anchor = node;
      connectivity = degree;
    }
  }

  const neighbours = graph.neighbours(anchor);
  const neighbourSet = new Set(neighbours);
  for (const other of graph.nodes()) {
    if (other === anchor || neighbourSet.has(other)) continue;
    connectivity = Math.min(connectivity, localNodeConnectivity(graph, anchor, other));
  }
  for (let i = 0; i < neighbours.length; i += 1) {
    for (let j = i + 1; j < neighbours.length; j += 1) {
      const [x, y] = [neighbours[i], neighbours[j]];
      if (graph.hasEdge(x, y)) continue;
      connectivity = Math.min(connectivity, localNodeConnectivity(graph, x, y));
    }
  }
  return connectivity;
}

