#!/usr/bin/env node
/**
 * Port of the reference Python script: builds a small weighted graph from five
 * integer command-line arguments and reports basic structural properties.
 */

import path from 'node:path';

import { ArgumentParser, intType } from './lib/cli/argparse.mjs';
import { Graph } from './lib/graph/graph.mjs';
import { minimumSpanningTree } from './lib/algorithms/mst.mjs';
import { dijkstraPath, dijkstraPathLength } from './lib/algorithms/shortest_paths.mjs';
import { bfsEdges, dfsEdges } from './lib/algorithms/traversal.mjs';
import { nodeConnectivity } from './lib/algorithms/connectivity.mjs';
import { reprBool, reprFloat, reprInt, reprList, reprTuple } from './lib/format/pyrepr.mjs';

const parser = new ArgumentParser(path.basename(process.argv[1] ?? 'test10.mjs'));
for (const name of ['a', 'b', 'c', 'd', 'e']) {
  parser.addArgument([`--${name}`], { type: intType, required: true });
}
const args = parser.parseArgs(process.argv.slice(2));

const G = new Graph();
G.addWeightedEdgesFrom([
  [args.a, args.b, 1.0],
  [args.b, args.c, 2.0],
  [args.c, args.d, 3.0],
  [args.d, args.e, 4.0],
  [args.a, args.e, 5.0],
]);

console.log(String(G.numberOfEdges())); // 获取边数量
console.log(reprFloat(G.getEdgeData(args.a, args.b).weight)); // 获取边权重
const mst = minimumSpanningTree(G); // 最小生成树
console.log(String(mst.numberOfEdges())); // MST边数量
console.log(reprBool(mst.hasEdge(args.a, args.b))); // 检查MST中的边

const length = dijkstraPathLength(G, args.a, args.e); // Dijkstra最短路径长度
console.log(typeof length === 'bigint' ? reprInt(length) : reprFloat(length));
console.log(reprList(dijkstraPath(G, args.a, args.e), reprInt)); // Dijkstra最短路径
console.log(reprList(bfsEdges(G, args.a), (edge) => reprTuple(edge, reprInt))); // BFS边
console.log(reprList(dfsEdges(G, args.a), (edge) => reprTuple(edge, reprInt))); // DFS边
console.log(String(nodeConnectivity(G))); // 节点连通性

