  [0x1680, 0x1680],
  [0x2000, 0x200a],
  [0x00a0, 0x00a0],
  [0x2028, 0x2029],
  [0x202f, 0x202f],
  [0x205f, 0x205f],
  [0x3000, 0x3000],
];

export class IntConversionError extends Error {}

export function pyInt(text) {
  const body = strip(text);
  let index = 0;
  let negative = false;

  if (body[index] === '+' || body[index] === '-') {
    negative = body[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasUnderscore = true; // an underscore may not lead the digits
  for (; index < body.length; index += 1) {
    const ch = body[index];
    if (ch === '_') {
      if (previousWasUnderscore) throw new IntConversionError();
      previousWasUnderscore = true;
      continue;
    }
    if (!DECIMAL_DIGIT.test(ch)) throw new IntConversionError();
    digits += String(digitValue(ch));
    previousWasUnderscore = false;
  }

  // Empty, or a trailing underscore.
  if (digits.length === 0 || previousWasUnderscore) throw new IntConversionError();

  const value = BigInt(digits);
  return negative ? -value : value;
}

function isWhitespace(ch) {
  const code = ch.codePointAt(0);
  return WHITESPACE_RANGES.some(([low, high]) => code >= low && code <= high);
}

function strip(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isWhitespace(text[start])) start += 1;
  while (end > start && isWhitespace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

/**
 * Value of a Unicode decimal digit. Every Nd block is a contiguous run of ten
 * code points starting at that script's zero, so walking back to the start of
 * the run yields the digit's weight.
 */
function digitValue(ch) {
  const code = ch.codePointAt(0);
  for (let offset = 0; offset < 10; offset += 1) {
    const previous = code - offset - 1;
    if (previous < 0 || !DECIMAL_DIGIT.test(String.fromCodePoint(previous))) return offset;
  }
  return 0;
}

