#!/usr/bin/env node
// Differential test: compares the port against the reference executable.
import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test10_executable';
const JS = '/output/test10.mjs';

function run(cmd, argv) {
  const res = { out: '', err: '', code: 0 };
  try {
    res.out = execFileSync(cmd[0], [...cmd.slice(1), ...argv], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
  } catch (e) {
    res.out = e.stdout ?? '';
    res.err = e.stderr ?? '';
    res.code = e.status ?? -1;
    return res;
  }
  return res;
}

function normalize(text) {
  return text.split('test10_executable').join('PROG').split('test10.mjs').join('PROG');
}

const cases = [];
// exhaustive over a small value set (heavy node collapsing)
const values = [1, 2, 3];
for (const a of values) for (const b of values) for (const c of values) for (const d of values) for (const e of values) {
  cases.push(['--a', `${a}`, '--b', `${b}`, '--c', `${c}`, '--d', `${d}`, '--e', `${e}`]);
}
// randomized over a wider set, including negatives and zero
for (let i = 0; i < 400; i += 1) {
  const pick = () => `${Math.floor(Math.random() * 9) - 4}`;
  cases.push(['--a', pick(), '--b', pick(), '--c', pick(), '--d', pick(), '--e', pick()]);
}
// argument-parsing edge cases
cases.push(
  [],
  ['--a', '1'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4'],
  ['--a=1', '--b=2', '--c=3', '--d=4', '--e=5'],
  ['--a', 'x', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1.5', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '0x10', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1_0', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1__0', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '_1', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1_', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '+5', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', ' 7 ', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '12', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '１２', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '१२', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '007', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '-0', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '99999999999999999999', '--b', '99999999999999999998', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '-3', '--b', '-4', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', '--f', '6'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', 'extra'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e'],
  ['--a', '--b', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', '--a', '9'],
  ['-a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--', '--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', '--'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', '--', 'foo'],
  ['--help'],
  ['--he'],
  ['-h'],
  ['--a', '1', '--b', '2', '--c', '3', '--d', '4', '--e', '5', '-h'],
  ['-hfoo'],
  ['--a', '-', '--b', '2', '--c', '3', '--d', '4', '--e', '5'],
);

let failures = 0;
for (const argv of cases) {
  const expected = run([EXE], argv);
  const actual = run(['node', JS], argv);
  const same =
    normalize(expected.out) === normalize(actual.out) &&
    normalize(expected.err) === normalize(actual.err) &&
    expected.code === actual.code;
  if (!same) {
    failures += 1;
    console.log('MISMATCH:', JSON.stringify(argv));
    console.log('  expected code', expected.code, JSON.stringify(normalize(expected.out)), JSON.stringify(normalize(expected.err)));
    console.log('  actual   code', actual.code, JSON.stringify(normalize(actual.out)), JSON.stringify(normalize(actual.err)));
    if (failures > 12) break;
  }
}
console.log(`${cases.length} cases, ${failures} mismatches`);
process.exit(failures === 0 ? 0 : 1);

